('en', 'text:DIX SPÉCIALITÉS COUVERTES PAR LA CLINIQUE, DU SUIVI DE GROSSESSE À LA CHIRURGIE ORTHOPÉDIQUE.', 'TEN SPECIALTIES COVERED BY THE CLINIC, FROM PREGNANCY MONITORING TO ORTHOPEDIC SURGERY.'),
('mg', 'text:DIX SPÉCIALITÉS COUVERTES PAR LA CLINIQUE, DU SUIVI DE GROSSESSE À LA CHIRURGIE ORTHOPÉDIQUE.', 'SPECIALITE FOLO NO SAKIN''NY CLINIC, HATRAMIN''NY FANAMBARAN''NY BEVOKA HANAO ORTHOPEDIC.'),
