('mg', 'text:PRISE EN CHARGE SPÉCIALISÉE.', 'FIkarakarana SPECIALIZED.'),
('en', 'text:TANÀNA', 'TANANA'),
('mg', 'text:TANÀNA', 'TANANA'),
('en', 'text:FAMPAHALALANA ARA-DALÀNA', 'FAMPAHALALANA ARA-DALÀNA'),
