('en', 'text:Le serveur met trop de temps à répondre. Vérifiez que l’API est démarrée.', 'The server is taking too long to respond. Verify that the API is started.'),
('mg', 'text:Le serveur met trop de temps à répondre. Vérifiez que l’API est démarrée.', 'Ela be vao mamaly ny mpizara. Hamarino fa natomboka ny API.'),
('en', 'text:Impossible de joindre le serveur. Vérifiez que l’API est démarrée sur le port 4000.', 'Unable to reach the server. Verify that the API is started on port 4000.'),
('mg', 'text:Impossible de joindre le serveur. Vérifiez que l’API est démarrée sur le port 4000.', 'Tsy afaka mankany amin''ny mpizara. Hamarino fa manomboka amin''ny seranana 4000 ny API.'),
('en', 'text:(listes paginées :', '(paginated lists:'),
('mg', 'text:(listes paginées :', '(Lisitra pejy:'),
('en', 'text:LE SERVEUR MET TROP DE TEMPS À RÉPONDRE. VÉRIFIEZ QUE L’API EST DÉMARRÉE.', 'THE SERVER IS TAKING TOO LONG TO RESPOND. VERIFY THAT THE API IS STARTED.'),
('mg', 'text:LE SERVEUR MET TROP DE TEMPS À RÉPONDRE. VÉRIFIEZ QUE L’API EST DÉMARRÉE.', 'Ela loatra ny SERVER vao mamaly. VERIFY FA MANOMBOKA NY API.'),
('en', 'text:IMPOSSIBLE DE JOINDRE LE SERVEUR. VÉRIFIEZ QUE L’API EST DÉMARRÉE SUR LE PORT 4000.', 'UNABLE TO CONTACT THE SERVER. VERIFY THAT THE API IS STARTED ON PORT 4000.'),
('mg', 'text:IMPOSSIBLE DE JOINDRE LE SERVEUR. VÉRIFIEZ QUE L’API EST DÉMARRÉE SUR LE PORT 4000.', 'TSY AFAKA Nifandray tamin''ny SERVER. HAmarino fa manomboka amin''ny PORT 4000 ny API.'),
('en', 'text:(LISTES PAGINÉES :', '(PAGINATED LISTS:'),
('mg', 'text:(LISTES PAGINÉES :', '(Lisitry ny PAGINA:'),
('en', 'text:Comment bien préparer sa consultation médicale', 'How to properly prepare for your medical consultation'),
('mg', 'text:Comment bien préparer sa consultation médicale', 'Ahoana ny fomba hanomanana tsara ny toro-hevitra ara-pitsaboana anao'),
('en', 'text:h:b5d61021:167', 'An effective consultation is being prepared. List of symptoms, current treatments, questions to ask: our advice to make the most of your time with your doctor.'),
('mg', 'text:h:b5d61021:167', 'Misy ny fifampidinihana mahomby eo am-panomanana. Lisitr''ireo soritr''aretina, fitsaboana amin''izao fotoana izao, fanontaniana apetraka: ny torohevitr''izy ireo mba hanararaotra ny fotoananao miaraka amin''ny dokotera.'),
('en', 'text:h:7394b807:212', 'Bring a list of your current treatments, including over-the-counter medications and dietary supplements. Drug interactions are a common cause of preventable adverse reactions.'),
('mg', 'text:h:7394b807:212', 'Mitondrà lisitr''ireo fitsaboana anao amin''izao fotoana izao, ao anatin''izany ny fanafody tsy misy fanafody sy ny fanampin-tsakafo. Ny fifandraisana amin''ny zava-mahadomelina dia antony mahazatra mahatonga ny voka-dratsy azo sorohina.'),
('en', 'text:h:9a37a9cf:171', 'Finally, write down your questions. Many patients forget half of what they wanted to ask once in the office. A simple memo on your phone is enough.'),
('mg', 'text:h:9a37a9cf:171', 'Farany, soraty ny fanontanianao. Marary maro no manadino ny antsasaky ny zavatra tiany hanontaniana indray mandeha tao amin''ny birao. Memo tsotra amin''ny findainao dia ampy.'),
('en', 'text:Notez la chronologie et l’intensité des symptômes.', 'Note the timing and intensity of symptoms.'),
('mg', 'text:Notez la chronologie et l’intensité des symptômes.', 'Mariho ny fotoana sy ny hamafin''ny soritr''aretina.'),
('en', 'text:Listez tous vos traitements, même ceux sans ordonnance.', 'List all your treatments, even those without a prescription.'),
('mg', 'text:Listez tous vos traitements, même ceux sans ordonnance.', 'Tanisao ny fitsaboana rehetra ataonao, na dia ireo tsy misy prescription aza.'),
('en', 'text:Préparez deux ou trois questions prioritaires.', 'Prepare two or three priority questions.'),
('mg', 'text:Préparez deux ou trois questions prioritaires.', 'Manomàna fanontaniana roa na telo laharam-pahamehana.'),
('en', 'text:Apportez vos examens et comptes-rendus récents.', 'Bring your recent exams and reports.'),
('mg', 'text:Apportez vos examens et comptes-rendus récents.', 'Ento ny fanadinana sy tatitra farany nataonao.'),
('en', 'text:Téléconsultation : mode d’emploi et bonnes pratiques', 'Teleconsultation: instructions for use and good practices'),
('mg', 'text:Téléconsultation : mode d’emploi et bonnes pratiques', 'Teleconsultation: torolàlana ampiasaina sy fomba fanao tsara'),
('en', 'text:Numérique', 'Digital'),
('mg', 'text:Numérique', 'Hafanàm-po'),
('en', 'text:Équipe MediClinic', 'MediClinic Team'),
('mg', 'text:Équipe MediClinic', 'Ekipa MediClinic'),
('en', 'text:h:af72f49:179', 'Medical videoconferencing is practical, but it requires a minimum of preparation. Here''s how to make your teleconsultation as useful as an in-person consultation.'),
('mg', 'text:h:af72f49:179', 'Ny fihaonambe ara-pitsaboana dia azo ampiharina, saingy mitaky fiomanana kely indrindra izany. Ity ny fomba hahatonga ny fifampidinihana amin''ny telefaonina ho mahasoa toy ny fifampidinihana manokana.'),
('en', 'text:h:f874ddf7:245', 'Teleconsultation is particularly suitable for monitoring chronic diseases, renewing prescriptions, interpreting results and simple symptoms. It does not replace the clinical examination when it is essential.'),
('mg', 'text:h:f874ddf7:245', 'Ny teleconsultation dia mety indrindra amin''ny fanaraha-maso ny aretina mitaiza, fanavaozana ny prescription, fandikana ny valiny ary soritr''aretina tsotra. Tsy mahasolo ny fizahana klinika izany rehefa tena ilaina izany.'),
('en', 'text:h:55d0bd9d:234', 'Sit in a quiet, well-lit place and check your connection a few minutes before time. Bring your Vitale card, your prescriptions and your blood pressure monitor or thermometer if you have one.'),
('mg', 'text:h:55d0bd9d:234', 'Mipetraha amin''ny toerana mangina sy mazava tsara ary jereo ny fifandraisanao minitra vitsy alohan''ny fotoana. Ento ny karatrao Vitale, ny taratasinao ary ny fanaraha-maso ny tosidra na ny thermometer raha manana izany ianao.'),
('en', 'text:h:b33c9da2:236', 'During the discussion, describe your symptoms precisely and do not hesitate to show a painful area on camera. At the end, check that you understand the dosage and the warning signs that should lead you to the emergency room.'),
('mg', 'text:h:b33c9da2:236', 'Mandritra ny fifanakalozan-kevitra, lazao tsara ny soritr''aretinao ary aza misalasala mampiseho faritra maharary amin''ny fakantsary. Amin''ny farany, jereo fa azonao ny dosage sy ny famantarana fampitandremana izay tokony hitondra anao any amin''ny efitrano vonjy maika.'),
('en', 'text:Testez votre matériel avant le rendez-vous.', 'Test your equipment before the appointment.'),
('mg', 'text:Testez votre matériel avant le rendez-vous.', 'Andramo ny fitaovanao alohan''ny fotoana.'),
('en', 'text:Préparez vos documents et vos constantes.', 'Prepare your documents and constants.'),
('mg', 'text:Préparez vos documents et vos constantes.', 'Omano ny antontan-taratasinao sy ny tsy miovaova.'),
('en', 'text:Demandez un compte-rendu écrit si nécessaire.', 'Ask for a written report if necessary.'),
('mg', 'text:Demandez un compte-rendu écrit si nécessaire.', 'Mangataha tatitra an-tsoratra raha ilaina.'),
('en', 'text:Prévention cardiovasculaire : les gestes qui comptent', 'Cardiovascular prevention: actions that count'),
('mg', 'text:Prévention cardiovasculaire : les gestes qui comptent', 'Fisorohana ny aretim-po: hetsika izay isaina'),
('en', 'text:Prévention', 'Prevention'),
('mg', 'text:Prévention', 'Fisorohana'),
('en', 'text:Dr Antoine Lefèvre', 'Dr Antoine Lefèvre'),
('mg', 'text:Dr Antoine Lefèvre', 'Dr Antoine Lefèvre'),
('en', 'text:Activité physique, alimentation, sommeil, tension artérielle : les leviers concrets pour prendre soin de votre cœur au quotidien, à tout âge.', 'Physical activity, diet, sleep, blood pressure: concrete levers to take care of your heart on a daily basis, at any age.'),
('mg', 'text:Activité physique, alimentation, sommeil, tension artérielle : les leviers concrets pour prendre soin de votre cœur au quotidien, à tout âge.', 'Ny asa ara-batana, ny sakafo, ny torimaso, ny tosi-drà: fitaovana beton mba hikarakarana ny fonao isan''andro, amin''ny taona rehetra.'),
('en', 'text:h:e66e4c4e:218', 'Cardiovascular diseases remain the leading cause of death in France. However, a significant proportion of risk factors are modifiable: tobacco, sedentary lifestyle, excess weight, hypertension, diabetes and cholesterol.'),
('mg', 'text:h:e66e4c4e:218', 'Ny aretim-po amin''ny aretim-po dia mijanona ho antony voalohany mahafaty any Frantsa. Na izany aza, ny ampahany lehibe amin''ny anton-javatra mety hampidi-doza dia azo ovaina: paraky, fomba fiaina mipetrapetraka, lanjany be loatra, hypertension, diabeta ary kolesterola.'),
('en', 'text:h:c91d5649:217', 'Thirty minutes of moderate physical activity five times a week is enough to significantly reduce the risk. Brisk walking, cycling or swimming are excellent choices, to be adapted to your physical condition.'),
('mg', 'text:h:c91d5649:217', 'Telopolo minitra ny fanaovana fanatanjahan-tena antonony in-dimy isan-kerinandro dia ampy hampihenana ny risika. Ny fandehanana haingana, ny bisikileta na ny milomano dia safidy tsara, hifanaraka amin''ny toe-batanao.'),
('en', 'text:Faire contrôler sa tension au moins une fois par an.', 'Have your blood pressure checked at least once a year.'),
('mg', 'text:Faire contrôler sa tension au moins une fois par an.', 'Asaivo jerena indray mandeha isan-taona farafahakeliny ny tosidra.'),
('en', 'text:Réduire sel, alcool et tabac.', 'Reduce salt, alcohol and tobacco.'),
('mg', 'text:Réduire sel, alcool et tabac.', 'Ahena ny sira, ny alikaola ary ny paraky.'),
('en', 'text:Sommeil et santé : reconstruire des nuits réparatrices', 'Sleep and health: rebuilding restful nights'),
('mg', 'text:Sommeil et santé : reconstruire des nuits réparatrices', 'Matory sy fahasalamana: manangana indray alina milamina'),
('en', 'text:Bien-être', 'Well-being'),
('mg', 'text:Bien-être', '-Panahy'),
('en', 'text:h:1ac2866c:160', 'Lack of sleep affects mood, immunity and cardiometabolic risk. A few simple routines can often improve the quality of the night.'),
('mg', 'text:h:1ac2866c:160', 'Ny tsy fahampian''ny torimaso dia misy fiantraikany amin''ny toe-po, ny tsy fahampiana ary ny risika cardiometabolic. Ny fanao tsotra vitsivitsy dia matetika afaka manatsara ny kalitaon''ny alina.'),
('en', 'text:h:e32b60e8:171', 'An adult needs an average of seven to nine hours of sleep per night. The regularity of bedtime and wake-up time is often more important than the total duration.'),
('mg', 'text:h:e32b60e8:171', 'Mila matory adiny fito ka hatramin''ny sivy isan''alina ny olon-dehibe iray. Ny faharetan''ny fotoana hatoriana sy ny fifohazana dia matetika manan-danja kokoa noho ny faharetan''ny total.'),
('en', 'text:h:a21f4ddd:165', 'Avoid bright screens in the hour before bed, as well as caffeine after 2 p.m. A cool, dark and quiet room helps you fall asleep.'),
('mg', 'text:h:a21f4ddd:165', 'Halaviro ny efijery mamirapiratra amin''ny ora alohan''ny hatoriana, ary koa ny kafeinina aorian''ny 2 ora. Ny efitrano mangatsiatsiaka, maizina ary mangina dia manampy anao hatory.'),
('en', 'text:h:87baad9e:227', 'If the difficulties persist for more than three weeks, or if they are accompanied by significant daytime sleepiness, talk to your doctor. Sleep disorders, such as apnea, require specific treatment.'),
('mg', 'text:h:87baad9e:227', 'Raha mitohy mandritra ny telo herinandro mahery ny fahasahiranana, na miaraka amin''ny torimaso lehibe antoandro, miresaha amin''ny dokotera. Ny aretin''ny torimaso, toy ny apnea, dia mitaky fitsaboana manokana.'),
('en', 'text:Se coucher et se lever à heures régulières.', 'Go to bed and get up at regular times.'),
('mg', 'text:Se coucher et se lever à heures régulières.', 'Mandehana matory ary mifohaza amin''ny fotoana tsy tapaka.'),
('en', 'text:Limiter les écrans le soir.', 'Limit screens in the evening.'),
('mg', 'text:Limiter les écrans le soir.', 'Fepetra ny efijery amin''ny hariva.'),
('en', 'text:Éviter la caféine en fin de journée.', 'Avoid caffeine at the end of the day.'),
('mg', 'text:Éviter la caféine en fin de journée.', 'Fadio ny kafeinina amin''ny faran''ny andro.'),
('en', 'text:Vaccination de l’adulte : êtes-vous à jour ?', 'Adult vaccination: are you up to date?'),
('mg', 'text:Vaccination de l’adulte : êtes-vous à jour ?', 'Vaksina ho an''ny olon-dehibe: manara-maso ve ianao?'),
('en', 'text:Diphtérie, tétanos, coqueluche, grippe, zona… Les rappels vaccinaux concernent aussi les adultes. Faites le point avec votre médecin traitant.', 'Diphtheria, tetanus, whooping cough, flu, shingles… Vaccination boosters also concern adults. Check with your doctor.'),
('mg', 'text:Diphtérie, tétanos, coqueluche, grippe, zona… Les rappels vaccinaux concernent aussi les adultes. Faites le point avec votre médecin traitant.', 'Ny difteria, ny tetanosy, ny kohaka, ny gripa, ny shingles… Ny fampiroboroboana ny vaksiny dia mahakasika ny olon-dehibe ihany koa. Jereo amin''ny dokoteranao.'),
('en', 'text:h:51caef47:214', 'Vaccination recommendations change with age and individual situations: pregnancy, chronic illness, exposed profession or travel. An up-to-date vaccination record helps avoid unnecessary reminders.'),
('mg', 'text:h:51caef47:214', 'Miova arakaraka ny taonany sy ny toe-javatra iainan''ny tsirairay ny tolo-kevitry ny fanaovana vaksiny: ny fitondrana vohoka, ny aretina mitaiza, ny asa miharihary na ny dia. Ny firaketana momba ny vaksiny vaovao dia manampy amin''ny fisorohana ny fampahatsiahivana tsy ilaina.'),
('en', 'text:h:93b45e34:232', 'The diphtheria-tetanus-pertussis booster is recommended every twenty years in adulthood. Flu vaccination is recommended every fall for people over 65 and those with risk factors.'),
('mg', 'text:h:93b45e34:232', 'Ny diphtheria-tetanus-pertussis booster dia atolotra isaky ny roapolo taona amin''ny olon-dehibe. Ny vaksinin''ny gripa dia asaina isaky ny fararano ho an''ny olona mihoatra ny 65 taona sy ireo manana antony mety hampidi-doza.'),
('en', 'text:h:dab1349b:151', 'The clinic offers walk-in vaccination sessions on certain afternoons. Consult the secretariat to find out the available slots.'),
('mg', 'text:h:dab1349b:151', 'Ny tobim-pitsaboana dia manolotra fivoriana fanaovana vaksiny mandeha an-tongotra amin''ny tolakandro sasany. Mankanesa any amin''ny sekretera mba hahitana ny toerana misy.'),
('en', 'text:Vérifier son carnet de vaccination.', 'Check your vaccination record.'),
('mg', 'text:Vérifier son carnet de vaccination.', 'Jereo ny firaketanao momba ny vaksiny.'),
('en', 'text:Vaccination grippe chaque automne pour les personnes à risque.', 'Flu vaccination every fall for people at risk.'),
('mg', 'text:Vaccination grippe chaque automne pour les personnes à risque.', 'Vaksina gripa isaky ny fararano ho an''ny olona atahorana.'),
('en', 'text:Votre dossier médical numérique, mode d’emploi', 'Your digital medical record, instructions for use'),
('mg', 'text:Votre dossier médical numérique, mode d’emploi', 'Ny firaketana ara-pitsaboana nomerika anao, torolàlana ampiasaina'),
('en', 'text:Ordonnances, résultats d’analyses et comptes-rendus centralisés : découvrez comment utiliser votre espace patient et protéger vos identifiants.', 'Prescriptions, analysis results and centralized reports: find out how to use your patient area and protect your identifiers.'),
('mg', 'text:Ordonnances, résultats d’analyses et comptes-rendus centralisés : découvrez comment utiliser votre espace patient et protéger vos identifiants.', 'Prescription, valim-panadihadiana ary tatitra afovoany: fantaro ny fomba fampiasana ny faritra misy anao ary arovy ny famantarana anao.'),
('en', 'text:h:6d472fb2:178', 'Your patient area brings together all the documents produced during your treatment: prescriptions, laboratory results, consultation reports and invoices.'),
('mg', 'text:h:6d472fb2:178', 'Ny faritry ny marary anao dia manangona ny antontan-taratasy rehetra novokarina nandritra ny fitsaboana anao: prescriptions, valin''ny laboratoara, tatitra momba ny fifampidinihana ary faktiora.'),
('en', 'text:h:68c63be2:218', 'Access is protected by strong authentication. Never share your password and always log out on a shared computer. If in doubt, reset your password immediately.'),
('mg', 'text:h:68c63be2:218', 'Ny fidirana dia voaaro amin''ny fanamarinana matanjaka. Aza mizara ny tenimiafinao na oviana na oviana ary mivoaha amin''ny solosaina iombonana. Raha misalasala, avereno avy hatrany ny tenimiafinao.'),
('en', 'text:h:10ca94c:182', 'You can download your documents in PDF format to send them to another healthcare professional. The file remains accessible for the entire legal retention period.'),
('mg', 'text:h:10ca94c:182', 'Azonao atao ny misintona ny antontan-taratasinao amin''ny endrika PDF handefasana azy ireo any amin''ny mpiasan''ny fahasalamana hafa. Mbola azo idirana mandritra ny fe-potoana fitazonana ara-dalàna ny rakitra.'),
('en', 'text:Un seul espace pour tous vos documents de santé.', 'A single space for all your health documents.'),
('mg', 'text:Un seul espace pour tous vos documents de santé.', 'Toerana tokana ho an''ny antontan-taratasy momba ny fahasalamanao rehetra.'),
('en', 'text:Connexion sécurisée et journalisée.', 'Secure, logged connection.'),
('mg', 'text:Connexion sécurisée et journalisée.', 'Fifandraisana azo antoka, voarakitra.'),
('en', 'text:Téléchargement PDF disponible.', 'PDF download available.'),
('mg', 'text:Téléchargement PDF disponible.', 'PDF azo alaina.'),
('en', 'text:COMMENT BIEN PRÉPARER SA CONSULTATION MÉDICALE', 'HOW TO PREPARE FOR YOUR MEDICAL CONSULTATION'),
('mg', 'text:COMMENT BIEN PRÉPARER SA CONSULTATION MÉDICALE', 'AHOANA NY FIOMANANA HO AN''NY FANDAHARANA MEDICAMENT'),
('en', 'text:h:98dbbf21:167', 'AN EFFECTIVE CONSULTATION IS BEING PREPARED. LIST OF SYMPTOMS, ONGOING TREATMENTS, QUESTIONS TO ASK: OUR ADVICE TO MAKE FULL OF YOUR TIME WITH YOUR DOCTOR.'),
('mg', 'text:h:98dbbf21:167', 'MIOMANANA NY FIKAMBANANA MAHASOA. Lisitry ny soritr''aretina, fitsaboana mitohy, FANONTANIANA Apetraka: TOROHEVITRA AMIN''NY FANAOVANA NY FOTOANAO AMIN''NY DOKTERANAO.'),
('en', 'text:h:301e69a7:212', 'BRING A LIST OF YOUR ONGOING TREATMENTS, INCLUDING OVER-THE-PRESCRIPTION MEDICATIONS AND DIETARY SUPPLEMENTS. DRUG INTERACTIONS ARE A COMMON CAUSE OF AVOIDABLE SIDE EFFECTS.'),
('mg', 'text:h:301e69a7:212', 'MITONDRA LISITRA NY FITONDRANA ATAOVY AO AMIN''IZANY FANAFODY MIALOHA AMIN''NY FOTOANA SY FAMPIANARANA FAHAGAGANA. NY Fifandraisana amin''ny zava-mahadomelina dia antony mahazatra amin''ny voka-dratsiny azo ialana.'),
('en', 'text:h:fccd04af:171', 'FINALLY, WRITE DOWN YOUR QUESTIONS. MANY PATIENTS FORGET HALF OF WHAT THEY WANTED TO ASK ONCE IN THE OFFICE. A SIMPLE MEMO ON YOUR PHONE IS ENOUGH.'),
('mg', 'text:h:fccd04af:171', 'FARANY, SORATY NY FANONTANIANAO. MARARY maro no manadino ny antsasa-manilan''ny zavatra tiany hanontaniana indray mandeha tao amin''ny birao. AMPY ATAO TSARA AO AMIN''NY TELEFONINAO.'),
('en', 'text:NOTEZ LA CHRONOLOGIE ET L’INTENSITÉ DES SYMPTÔMES.', 'NOTE THE TIMELINE AND INTENSITY OF SYMPTOMS.'),
('mg', 'text:NOTEZ LA CHRONOLOGIE ET L’INTENSITÉ DES SYMPTÔMES.', 'Mariho ny fe-potoana sy ny hamafin''ny soritr''aretina.'),
('en', 'text:LISTEZ TOUS VOS TRAITEMENTS, MÊME CEUX SANS ORDONNANCE.', 'LIST ALL YOUR TREATMENTS, EVEN THOSE WITHOUT A PRESCRIPTION.'),
('mg', 'text:LISTEZ TOUS VOS TRAITEMENTS, MÊME CEUX SANS ORDONNANCE.', 'TANISAO NY FITONDRANA REHETRA, NA IREO TSY MISY PRESCRIPTION.'),
('en', 'text:PRÉPAREZ DEUX OU TROIS QUESTIONS PRIORITAIRES.', 'PREPARE TWO OR THREE PRIORITY QUESTIONS.'),
('mg', 'text:PRÉPAREZ DEUX OU TROIS QUESTIONS PRIORITAIRES.', 'MANOMANANA FANONTANIANA ALOHA NA TELO.'),
('en', 'text:APPORTEZ VOS EXAMENS ET COMPTES-RENDUS RÉCENTS.', 'BRING YOUR RECENT EXAMS AND REPORTS.'),
('mg', 'text:APPORTEZ VOS EXAMENS ET COMPTES-RENDUS RÉCENTS.', 'MITONDRA NY FANADINANAO SY NY TATITRA VAO.'),
('en', 'text:TÉLÉCONSULTATION : MODE D’EMPLOI ET BONNES PRATIQUES', 'TELECONSULTATION: INSTRUCTIONS AND GOOD PRACTICES'),
('mg', 'text:TÉLÉCONSULTATION : MODE D’EMPLOI ET BONNES PRATIQUES', 'TELECONSULTATION: FAMPIANARANA SY FANAOVANA TSARA'),
('en', 'text:NUMÉRIQUE', 'DIGITAL'),
('mg', 'text:NUMÉRIQUE', 'Hafanàm-po'),
('en', 'text:ÉQUIPE MEDICLINIC', 'MEDICLINIC TEAM'),
('mg', 'text:ÉQUIPE MEDICLINIC', 'EKEKY MEDICLINIC'),
('en', 'text:h:def30c69:179', 'MEDICAL VIDEO CONFERENCE IS PRACTICAL, BUT IT REQUIRES A MINIMUM OF PREPARATION. HERE’S HOW TO MAKE YOUR TELECONSULTATION AS USEFUL AS AN IN-PERSON CONSULTATION.'),
('mg', 'text:h:def30c69:179', 'NY VIDEO MEDICAL CONFERENCE dia azo ampiharina, fa mila fiomanana faran''izay kely. IZAO NO ATAO HO MAHASOA HO COMSULTATION AMIN''NY OLONA NY TELECONSULTATION.'),
('en', 'text:h:83605c37:245', 'TELECONSULTATION IS PARTICULARLY SUITABLE FOR MONITORING CHRONIC DISEASES, RENEWING PRESCRIPTIONS, INTERPRETATION OF RESULTS AND SIMPLE SYMPTOMS. IT DOES NOT REPLACE CLINICAL EXAMINATION WHEN IT IS ESSENTIAL.'),
('mg', 'text:h:83605c37:245', 'NY TELECONSULTATION dia mety tsara indrindra amin''ny fanaraha-maso ny aretina mitaiza, ny fanavaozam-baovao, ny fandikana ny voka-dratsiny ary ny soritr''aretina tsotra. TSY MANOLO NY FANADINANA KLINIKA REHEFA ILAINA.'),
('en', 'text:h:e2cae9dd:234', 'SET YOURSELF IN A QUIET, PROPERLY LIT PLACE, AND CHECK YOUR CONNECTION A FEW MINUTES BEFORE TIME. HAVE YOUR VITAL CARD, YOUR PRESCRIPTIONS AND YOUR PRESSURE MONITOR OR THERMOMETER IF YOU HAVE ONE.'),
('mg', 'text:h:e2cae9dd:234', 'MITONDRA NY TENANAO EO AMIN''NY TOERANA TONINA, MAZAVA TSARA, ARY ZARAO NY Fifandraisanao, minitra vitsy alohan''ny fotoana. ANAO NY KARATANAO VITAL, NY PRESCRIPTION ARY NY PRESSURE MONITOR NA THERMOMETER RAHA MANANA.'),
('en', 'text:h:b540e1e2:236', 'DURING THE EXCHANGE, ACCURATELY DESCRIBE YOUR SYMPTOMS AND DO NOT HESITATE TO SHOW A PAINFUL AREA ON CAMERA. AT THE END, CHECK THAT YOU HAVE UNDERSTOOD THE DOSAGE AND THE WARNING SIGNS THAT SHOULD LEAD YOU TO THE EMERGENCY.'),
('mg', 'text:h:b540e1e2:236', 'AO AMIN''NY FANAOVANA DIA FILAZANA TSARA TSARA IREO SYSTEM ANAO ARY AZA MIASA ANAREO MANDEHA FARITRA MANJARY AMIN''NY CAMERA. AMIN''NY FARANY, IZAY AZO ATAO NY DOSAGE SY NY FAMPITANDREMANA IZAY TOKONY HITONDRA ANAO AMIN''NY FAMPIANARANA.'),
('en', 'text:TESTEZ VOTRE MATÉRIEL AVANT LE RENDEZ-VOUS.', 'TEST YOUR EQUIPMENT BEFORE THE APPOINTMENT.'),
('mg', 'text:TESTEZ VOTRE MATÉRIEL AVANT LE RENDEZ-VOUS.', 'ZAHAO NY FITAOVANAO ALOHAN''NY FIHAONANA.'),
('en', 'text:PRÉPAREZ VOS DOCUMENTS ET VOS CONSTANTES.', 'PREPARE YOUR DOCUMENTS AND CONSTANTS.'),
('mg', 'text:PRÉPAREZ VOS DOCUMENTS ET VOS CONSTANTES.', 'OMANO NY TARATASINAO SY NY FAMERENANA NY TOETR''ANATIN''NY VATANAO.'),
('en', 'text:DEMANDEZ UN COMPTE-RENDU ÉCRIT SI NÉCESSAIRE.', 'ASK FOR A WRITTEN REPORT IF NECESSARY.'),
('mg', 'text:DEMANDEZ UN COMPTE-RENDU ÉCRIT SI NÉCESSAIRE.', 'MANGATAHA TATITRA AN-TSORATRA RAHA ILAINA.'),
('en', 'text:PRÉVENTION CARDIOVASCULAIRE : LES GESTES QUI COMPTENT', 'CARDIOVASCULAR PREVENTION: ACTION THAT COUNTS'),
('mg', 'text:PRÉVENTION CARDIOVASCULAIRE : LES GESTES QUI COMPTENT', 'FISOROHANA NY CARDIOVASCULAR: HETSIKA MITANDRINA'),
('en', 'text:PRÉVENTION', 'PREVENTION'),
('mg', 'text:PRÉVENTION', 'FISOROHANA'),
('en', 'text:DR ANTOINE LEFÈVRE', 'DR ANTOINE LEFÈVRE'),
('mg', 'text:DR ANTOINE LEFÈVRE', 'DR ANTOINE LEFÈVRE'),
('en', 'text:ACTIVITÉ PHYSIQUE, ALIMENTATION, SOMMEIL, TENSION ARTÉRIELLE : LES LEVIERS CONCRETS POUR PRENDRE SOIN DE VOTRE CŒUR AU QUOTIDIEN, À TOUT ÂGE.', 'PHYSICAL ACTIVITY, FOOD, SLEEP, BLOOD PRESSURE: CONCRETE LEVERS TO TAKE CARE OF YOUR HEART EVERY DAY, AT ANY AGE.'),
('mg', 'text:ACTIVITÉ PHYSIQUE, ALIMENTATION, SOMMEIL, TENSION ARTÉRIELLE : LES LEVIERS CONCRETS POUR PRENDRE SOIN DE VOTRE CŒUR AU QUOTIDIEN, À TOUT ÂGE.', 'ASA ASA, sakafo, matory, tosi-drà: lever concrete hitandrina ny fo isan''andro, na inona na inona taona.'),
('en', 'text:h:de3641ee:218', 'CARDIOVASCULAR DISEASES REMAIN THE LEADING CAUSE OF MORTALITY IN FRANCE. YET, A SIGNIFICANT PART OF RISK FACTORS IS MODIFIABLE: TOBACCO, SEDENTARITY, OVERWEIGHT, HYPERTENSION, DIABETES AND CHOLESTEROL.'),
('mg', 'text:h:de3641ee:218', 'NY ARETINA CARDIOVASCULARE NO TOKONY MAHATONGA NY FAHAFATESANA ATO FRANCE. ANEFA, NY Ampahany manan-danja amin''ny risika dia azo ovaina: paraky, fipetrahana, lanja be loatra, fiakaran''ny tosidrà, diabeta ary kolesterola.'),
('en', 'text:h:bd574009:217', 'THIRTY MINUTES OF MODERATE PHYSICAL ACTIVITY FIVE TIMES PER WEEK IS ENOUGH TO SIGNIFICANTLY REDUCE THE RISK. Brisk WALKING, BIKING OR SWIMMING ARE EXCELLENT CHOICES, TO BE ADAPTED TO YOUR PHYSICAL CONDITION.'),
('mg', 'text:h:bd574009:217', 'TELOpolo minitra amin''ny asa ara-batana antonony indimy isan-kerinandro dia ampy mba hampihenana ny risika. SAFIDY LEHIBE NY FIJAKANA FAHAGAGANA, FITSIPIKA NA FITONDRANA, HANAFANA NY FAHAFANAO.'),
('en', 'text:FAIRE CONTRÔLER SA TENSION AU MOINS UNE FOIS PAR AN.', 'HAVE YOUR PRESSURE CHECKED AT LEAST ONCE A YEAR.'),
('mg', 'text:FAIRE CONTRÔLER SA TENSION AU MOINS UNE FOIS PAR AN.', 'ATAOVY NY TOERANAO Indray mandeha isan-taona farafahakeliny.'),
('en', 'text:RÉDUIRE SEL, ALCOOL ET TABAC.', 'REDUCE SALT, ALCOHOL AND TOBACCO.'),
('mg', 'text:RÉDUIRE SEL, ALCOOL ET TABAC.', 'Ahena ny sira, ny toaka ary ny paraky.'),
('en', 'text:SOMMEIL ET SANTÉ : RECONSTRUIRE DES NUITS RÉPARATRICES', 'SLEEP AND HEALTH: REBUILDING REPAIRING NIGHTS'),
('mg', 'text:SOMMEIL ET SANTÉ : RECONSTRUIRE DES NUITS RÉPARATRICES', 'MATORY SY NY FAHASALAMANA: MANORONANA MANDRAKIZAY NY ALALINY'),
('en', 'text:BIEN-ÊTRE', 'WELL-BEING'),
('mg', 'text:BIEN-ÊTRE', '-Panahy'),
('en', 'text:h:bee831ec:160', 'LACK OF SLEEP AFFECTS MOOD, IMMUNITY AND CARDIOMETABOLIC RISK. A FEW SIMPLE ROUTINES CAN OFTEN IMPROVE THE QUALITY OF NIGHTS.'),
('mg', 'text:h:bee831ec:160', 'Ny tsy fahampian''ny torimaso dia misy fiantraikany amin''ny toe-po, ny tsimatimanota ary ny loza mety hitranga amin''ny cardiometabolic. ATAOVY tsotsotra vitsivitsy dia afaka manatsara ny kalitaon''ny alina.'),
('en', 'text:h:420f77e8:171', 'AN ADULT NEEDS AN AVERAGE OF SEVEN TO NINE HOURS OF SLEEP PER NIGHT. THE REGULARITY OF SETTING AND RISING TIMES IS OFTEN MORE IMPORTANT THAN THE TOTAL DURATION.'),
('mg', 'text:h:420f77e8:171', 'MILA MATORY AMIN''NY FITO KA KAMARINA ADIN''NY sivy isan''alina ny olon-dehibe iray. NY FAHAFARAN''NY FAMPIANARANA SY NY FOTOANA MISOKATRA IZAY MATETIKA NO ZAVA-DEHIBE NOHO NY FOTOANA TOTALANA.'),
('en', 'text:h:ef4a195d:165', 'AVOID LIGHT SCREENS IN THE HOUR BEFORE BEING BED, AS WELL AS CAFFEINE AFTER 2 P.M. A COOL, DARK AND QUIET ROOM PROMOTES FALLING ASLEEP.'),
('mg', 'text:h:ef4a195d:165', 'FAHALALANA NY FIRAISANA MAZAVA AO AMIN’NY ORA MIALOHAN’NY FAMPANDRIANA, TOY NY KAFEINA AORIAN’NY 2 ora tolakandro. Efitrano mangatsiatsiaka, maizina ary mangina dia mandrisika ny torimaso.'),
('en', 'text:h:97a50e9e:227', 'IF THE DIFFICULTIES PERSIST FOR MORE THAN THREE WEEKS, OR IF THEY ARE ACCOMPANIED BY SIGNIFICANT DAYTIME Drowsiness, TALK TO YOUR DOCTOR. SLEEP DISORDERS, LIKE APNEA, REQUIRE SPECIFIC TREATMENT.'),
('mg', 'text:h:97a50e9e:227', 'RAHA MITOHY MANDRAKIZAY MANDRAKIZAY TELO HERINANDRO mahery ny fahasahiranana, na miaraka amin''ny faharendremana lehibe mandritra ny andro, dia miresaha amin''ny dokoteranao. MISY MISY MATORY, TOY NY APNEA, MILA FITSIPIKA.'),
('en', 'text:SE COUCHER ET SE LEVER À HEURES RÉGULIÈRES.', 'GO TO BED AND GET UP AT REGULAR TIMES.'),
('mg', 'text:SE COUCHER ET SE LEVER À HEURES RÉGULIÈRES.', 'Mandehana matory ary mifohaza amin''ny fotoana mahazatra.'),
('en', 'text:LIMITER LES ÉCRANS LE SOIR.', 'LIMIT SCREENS IN THE EVENING.'),
('mg', 'text:LIMITER LES ÉCRANS LE SOIR.', 'FITAOVANA ERAN-TSARA AMIN''NY HARIVA.'),
('en', 'text:ÉVITER LA CAFÉINE EN FIN DE JOURNÉE.', 'AVOID CAFFEINE AT THE END OF THE DAY.'),
('mg', 'text:ÉVITER LA CAFÉINE EN FIN DE JOURNÉE.', 'FAHALALANA NY KAFEINA AMIN''NY FARAN''NY ANDRO.'),
('en', 'text:VACCINATION DE L’ADULTE : ÊTES-VOUS À JOUR ?', 'ADULT VACCINATION: ARE YOU UP TO DATE?'),
('mg', 'text:VACCINATION DE L’ADULTE : ÊTES-VOUS À JOUR ?', 'VAKSININA HO AN''NY OLONA: MAHAFINARITRA VE IANAO?'),
('en', 'text:DIPHTÉRIE, TÉTANOS, COQUELUCHE, GRIPPE, ZONA… LES RAPPELS VACCINAUX CONCERNENT AUSSI LES ADULTES. FAITES LE POINT AVEC VOTRE MÉDECIN TRAITANT.', 'DIPHTERIA, TETANOUS, PERPOSTING COUGH, FLU, SHINGLES… VACCINE RECALLS ALSO CONCERN ADULTS. CHECK UP WITH YOUR ATTENDING DOCTOR.'),
('mg', 'text:DIPHTÉRIE, TÉTANOS, COQUELUCHE, GRIPPE, ZONA… LES RAPPELS VACCINAUX CONCERNENT AUSSI LES ADULTES. FAITES LE POINT AVEC VOTRE MÉDECIN TRAITANT.', 'DIPHTERIE, TETANOUS, KOFAKA, FLU, SHINGLES… MAMPIASA NY OLONA KOA NY VACCINE. MIJERY AMIN''NY DOKTERANA ANAO.'),
('en', 'text:h:841e8927:214', 'VACCINE RECOMMENDATIONS CHANGE WITH AGE AND INDIVIDUAL SITUATIONS: PREGNANCY, CHRONIC ILLNESS, EXPOSED OCCUPATION OR TRAVEL. AN UP-TO-DATE VACCINATION RECORD CAN AVOID UNNECESSARY RECALLS.'),
('mg', 'text:h:841e8927:214', 'MIOVA AMIN''NY TAONA SY NY TOERANA ATAOVY NY VAKSINY: BEVOKATRA, ARETINA TSY MISY, FANAOVANA TSY MIARAKA NA FIVAVAHANA. AFAKA MIsoroka ny fahatsiarovan-tena tsy ilaina ny firaketana momba ny vaksiny.'),
('en', 'text:h:193736b4:232', 'THE DIPHTERIA-TETANOUS-Pertussis BACKLOCK IS RECOMMENDED EVERY TWENTY YEARS IN ADULTS. FLU VACCINATION IS RECOMMENDED EACH FALL FOR PEOPLE OVER 65 AND THOSE WITH RISK FACTORS.'),
('mg', 'text:h:193736b4:232', 'NY DIPHTERIA-TETANOUS-Pertussis BACKLOCK NO TOROHEVITRA Isaky ny roapolo taona amin''ny olon-dehibe. TOROHEVITRA NY VAKSININA FLU Isaky ny fararano ho an''ireo olona mihoatra ny 65 taona sy ireo manana risika.'),
('en', 'text:h:81c9d4bb:151', 'THE CLINIC OFFERS VACCINATION SESSIONS WITHOUT APPOINTMENT SOME AFTERNOONS. CONSULT THE SECRETARIAT TO FIND OUT AVAILABLE SLOTS.'),
('mg', 'text:h:81c9d4bb:151', 'Ny tobim-pahasalamana dia manome VAKSININA TSY MISY FANDINIHANA TOLAKAY. MITONDRA AMIN''NY SECRETARIAT MBA HITADY SLOT MISY.'),
('en', 'text:VÉRIFIER SON CARNET DE VACCINATION.', 'CHECK YOUR VACCINATION RECORD.'),
('mg', 'text:VÉRIFIER SON CARNET DE VACCINATION.', 'JEREO NY RAKOTOANAO VAKSININAO.'),
('en', 'text:VACCINATION GRIPPE CHAQUE AUTOMNE POUR LES PERSONNES À RISQUE.', 'FLU VACCINATION EACH FALL FOR PEOPLE AT RISK.'),
('mg', 'text:VACCINATION GRIPPE CHAQUE AUTOMNE POUR LES PERSONNES À RISQUE.', 'VACCINATION FLU ISAN''NY LAVOTRA HO AN''NY OLONA AMBONINA.'),
