('mg', 'text:VOTRE DOSSIER MÉDICAL NUMÉRIQUE, MODE D’EMPLOI', 'NY RECORDE MEDICAL DIGITAL ANAO, TORO-TORO AMINAO'),
('en', 'text:ORDONNANCES, RÉSULTATS D’ANALYSES ET COMPTES-RENDUS CENTRALISÉS : DÉCOUVREZ COMMENT UTILISER VOTRE ESPACE PATIENT ET PROTÉGER VOS IDENTIFIANTS.', 'PRESCRIPTIONS, ANALYSIS RESULTS AND CENTRALIZED REPORTS: DISCOVER HOW TO USE YOUR PATIENT AREA AND PROTECT YOUR IDENTIFIERS.'),
('mg', 'text:ORDONNANCES, RÉSULTATS D’ANALYSES ET COMPTES-RENDUS CENTRALISÉS : DÉCOUVREZ COMMENT UTILISER VOTRE ESPACE PATIENT ET PROTÉGER VOS IDENTIFIANTS.', 'TOROHEVITRA, VOKATRY NY ANALYSIS SY NY TANTARA IFONANA: MAHITA ny fomba ampiasana ny faritry ny mararin''ny marary ARY MIARO NY MPANONTANAO.'),
('en', 'text:h:9422b532:178', 'YOUR PATIENT AREA GROUPS ALL OF THE DOCUMENTS PRODUCED DURING YOUR CARE: PRESCRIPTIONS, LABORATORY RESULTS, CONSULTATION REPORTS AND INVOICES.'),
('mg', 'text:h:9422b532:178', 'NY FARITRA ARA-KARAZANAO dia manangana ny antontan-taratasy rehetra navoaka nandritra ny fikarakarana anao: PRESCRIPTIONS, LABORATORY RESULTS, RESULTS CONSULTATION AND INVOICES.'),
('en', 'text:h:f1ca2982:218', 'ACCESS IS PROTECTED BY STRONG AUTHENTICATION. NEVER SHARE YOUR PASSWORD AND ALWAYS LOG OUT ON A SHARED COMPUTER. IF IN DOUBT, RESET YOUR PASSWORD IMMEDIATELY.'),
('mg', 'text:h:f1ca2982:218', 'ACCESS dia voaaro amin''ny Authentication STRONG. AZA MIzara ny PASSWORAN-ANAO ARY MIDIA FOANA AMIN''NY Solosaina Izarana. Raha misalasala ianao dia avereno avy hatrany ny tenimiafinao.'),
('en', 'text:h:9a031acc:182', 'YOU CAN DOWNLOAD YOUR DOCUMENTS IN PDF FORMAT TO TRANSMIT THEM TO ANOTHER HEALTH PROFESSIONAL. THE FILE REMAINS ACCESSIBLE FOR THE ENTIRE LEGAL RETENTION PERIOD.'),
('mg', 'text:h:9a031acc:182', 'AFAKA MIsintona ny antontan-taratasinao amin''ny format PDF ianao mba hamindrana azy ireo any amin''ny matihanina ara-pahasalamana hafa. MITOHY AZO AZO AZO ATAO NY IRAISANA MANDRAKIZAY MANDRAKIZAY NY FOTOANA FOTOANA ARA-DALANA.'),
