('en', 'text:MESSAGE ENVOYÉ. NOTRE SECRÉTARIAT VOUS RÉPOND SOUS 24H OUVRÉES.', 'MESSAGE SENT. OUR SECRETARIAT WILL RESPOND TO YOU WITHIN 24 BUSINESS HOURS.'),
('mg', 'text:MESSAGE ENVOYÉ. NOTRE SECRÉTARIAT VOUS RÉPOND SOUS 24H OUVRÉES.', 'HAFATRA. HAMALY ANAO AO anatin''ny 24 ora fiasana ny SECRETARIAT.'),
('en', 'text:UNE QUESTION SUR UN RENDEZ-VOUS, UNE FACTURE OU VOTRE DOSSIER MÉDICAL ? ÉCRIVEZ-NOUS OU APPELEZ DIRECTEMENT LE SECRÉTARIAT.', 'A QUESTION ABOUT AN APPOINTMENT, AN INVOICE OR YOUR MEDICAL RECORD? WRITE TO US OR CALL THE SECRETARIAT DIRECTLY.'),
('mg', 'text:UNE QUESTION SUR UN RENDEZ-VOUS, UNE FACTURE OU VOTRE DOSSIER MÉDICAL ? ÉCRIVEZ-NOUS OU APPELEZ DIRECTEMENT LE SECRÉTARIAT.', 'FANONTANIANA MOMBA NY FANENDRENANA, INVOICE SA NY RECORD MEDICAL? MANORATRA AMINAY NA MIANTSO MIVANTANA NY SECRETARIAT.'),
('en', 'text:ÉCRIRE', 'TO WRITE'),
('mg', 'text:ÉCRIRE', 'MANORATRA'),
('en', 'text:DÉCRIVEZ VOTRE DEMANDE EN QUELQUES LIGNES…', 'DESCRIBE YOUR REQUEST IN A FEW LINES…'),
('mg', 'text:DÉCRIVEZ VOTRE DEMANDE EN QUELQUES LIGNES…', 'LAZARIO AMIN''NY ANdalana vitsivitsy ny fangatahanao…'),
