('en', 'text:Rechercher un médecin, une spécialité…', 'Search for a doctor, a specialty…'),
('mg', 'text:Rechercher un médecin, une spécialité…', 'Mitadiava dokotera, manampahaizana manokana…'),
('en', 'text:Aucun médecin ne correspond à votre recherche', 'No doctor matches your search'),
('mg', 'text:Aucun médecin ne correspond à votre recherche', 'Tsy misy dokotera mifanandrify amin''ny fikarohanao'),
('en', 'text:Essayez une autre spécialité ou effacez les filtres.', 'Try another specialty or clear the filters.'),
('mg', 'text:Essayez une autre spécialité ou effacez les filtres.', 'Manandrama manokana hafa na esory ny sivana.'),
('en', 'text:VOS DONNÉES NE SONT UTILISÉES QUE POUR TRAITER VOTRE DEMANDE.', 'YOUR DATA IS ONLY USED TO PROCESS YOUR REQUEST.'),
('en', 'text:RÉSERVER', 'TO BOOK'),
