('en', 'text:AUCUN MÉDECIN NE CORRESPOND À VOTRE RECHERCHE', 'NO DOCTOR MATCHES YOUR SEARCH'),
('mg', 'text:AUCUN MÉDECIN NE CORRESPOND À VOTRE RECHERCHE', 'TSY MISY DOKTERANA Mifanaraka amin''ny fikarohanao'),
('en', 'text:ESSAYEZ UNE AUTRE SPÉCIALITÉ OU EFFACEZ LES FILTRES.', 'TRY ANOTHER SPECIALTY OR CLEAR THE FILTERS.'),
('mg', 'text:ESSAYEZ UNE AUTRE SPÉCIALITÉ OU EFFACEZ LES FILTRES.', 'MANAndrama SPECIALITE HAFA NA FAFASO NY FILTER.'),
('en', 'text:Toutes les réponses,', 'All the answers,'),
('mg', 'text:Toutes les réponses,', 'Ny valiny rehetra,'),
('en', 'text:au même endroit', 'in the same place'),
('mg', 'text:au même endroit', 'amin’ny toerana iray ihany'),
('en', 'text:Notre équipe vous répond sous 24h ouvrées.', 'Our team will respond to you within 24 working hours.'),
('mg', 'text:Notre équipe vous répond sous 24h ouvrées.', 'Ny ekipanay dia hamaly anao ao anatin''ny 24 ora fiasana.'),
('en', 'text:Nous écrire', 'Write to us'),
('mg', 'text:Nous écrire', 'Manorata aminay'),
('en', 'text:h:a5c32af6:231', 'You can book online from the “Make an appointment” page, choose your practitioner and your slot, then receive immediate confirmation. The secretariat can still be reached by telephone for special requests.'),
('mg', 'text:h:a5c32af6:231', 'Azonao atao ny mamandrika an-tserasera amin''ny pejy "Manaova fotoana", safidio ny mpitsabo anao sy ny toerana misy anao, ary mahazo fanamafisana avy hatrany. Mbola azo antsoina amin''ny telefaona ny sekretera raha mila fangatahana manokana.'),
('en', 'text:Puis-je annuler ou déplacer un rendez-vous ?', 'Can I cancel or reschedule an appointment?'),
('mg', 'text:Puis-je annuler ou déplacer un rendez-vous ?', 'Afaka manafoana na manendry fotoana indray ve aho?'),
('en', 'text:h:f796ccef:191', 'Yes. From your patient area, select the appointment concerned then choose “Cancel”. Please notify at least 24 hours in advance to free up the slot for another patient.'),
('mg', 'text:h:f796ccef:191', 'Eny. Avy amin''ny faritra misy anao marary, safidio ny fotoana voatondro ary safidio ny "Cancel". Ampahafantaro 24 ora mialoha fara-fahakeliny mba hanafaka ny slot ho an''ny marary hafa.'),
('en', 'text:h:822f554c:191', 'Your Vitale card, an identity document, your health insurance card and, if possible, your prescriptions and recent test results. For a first meeting, arrive ten minutes early.'),
('mg', 'text:h:822f554c:191', 'Ny karatry ny Vitale-nao, ny taratasim-panananao, ny karatry ny fiantohana ara-pahasalamanao ary, raha azo atao, ny taratasinao sy ny valin''ny fitsapana vao haingana. Ho an''ny fivoriana voalohany, tongava folo minitra mialoha.'),
('en', 'text:La téléconsultation est-elle remboursée ?', 'Is teleconsultation reimbursed?'),
('mg', 'text:La téléconsultation est-elle remboursée ?', 'Averina ve ny teleconsultation?'),
('en', 'text:h:30ba5dc9:180', 'It is covered under the same conditions as a consultation at the office, if it is carried out by an approved doctor. Your mutual insurance company can complete the reimbursement.'),
('mg', 'text:h:30ba5dc9:180', 'Sarona amin''ny fepetra mitovy amin''ny fifampidinihana any amin''ny birao izy io, raha dokotera ankatoavina no manao izany. Ny orinasam-piantohana misy anao dia afaka mamita ny fanonerana.'),
('en', 'text:Comment accéder à ma visioconférence ?', 'How do I access my videoconference?'),
('mg', 'text:Comment accéder à ma visioconférence ?', 'Ahoana no hidirana amin''ny fihaonambe vidéo?'),
('en', 'text:h:432dcbcc:157', 'Once your request is approved, a secure link appears in “My teleconsultations”. The connection button activates ten minutes before the scheduled time.'),
('mg', 'text:h:432dcbcc:157', 'Rehefa nekena ny fangatahanao dia misy rohy azo antoka hita ao amin''ny "My teleconsultsments". Ny bokotra fifandraisana dia mihetsika folo minitra alohan''ny fotoana voatondro.'),
('en', 'text:Quel matériel est nécessaire ?', 'What equipment is needed?'),
('mg', 'text:Quel matériel est nécessaire ?', 'Inona no fitaovana ilaina?'),
('en', 'text:h:a91b41bd:171', 'A recent computer or smartphone, a stable internet connection, a webcam and a microphone. A calm and bright place clearly improves the quality of the exchange.'),
('mg', 'text:h:a91b41bd:171', 'Solosaina na smartphone vao haingana, fifandraisana Internet stable, webcam ary mikrô. Ny toerana tony sy mamirapiratra dia manatsara mazava tsara ny kalitaon''ny fifanakalozana.'),
('en', 'text:Comment créer mon espace patient ?', 'How do I create my patient space?'),
('mg', 'text:Comment créer mon espace patient ?', 'Ahoana no hamoronako ny toerana misy ny marary?'),
('en', 'text:h:b4613ff2:169', 'Click on “Create my space”, fill in your information and validate your email. You will then be able to view your appointments, prescriptions, results and invoices.'),
('mg', 'text:h:b4613ff2:169', 'Tsindrio ny "Create my space", fenoy ny mombamomba anao ary manamarina ny mailakao. Avy eo ianao dia afaka mijery ny fotoana, ny prescriptions, ny valiny ary ny faktiora.'),
('en', 'text:Mes données sont-elles protégées ?', 'Is my data protected?'),
('mg', 'text:Mes données sont-elles protégées ?', 'Voaaro ve ny angonako?'),
('en', 'text:h:69013f38:167', 'Yes. Health data is hosted in France, encrypted and accessible only to authorized professionals. Each access is logged in accordance with the GDPR.'),
('mg', 'text:h:69013f38:167', 'Eny. Ny angon-drakitra momba ny fahasalamana dia nampiantranoina any Frantsa, voatahiry ary tsy azo idirana afa-tsy amin''ny matihanina manam-pahefana. Ny fidirana tsirairay dia voasoratra mifanaraka amin''ny GDPR.'),
('en', 'text:Puis-je télécharger mon dossier ?', 'Can I download my file?'),
('mg', 'text:Puis-je télécharger mon dossier ?', 'Afaka misintona ny fichier-ko ve aho?'),
('en', 'text:h:add893f9:160', 'You can download your prescriptions and invoices in PDF format. To obtain a complete copy of your file, send a written request to the secretariat.'),
('mg', 'text:h:add893f9:160', 'Azonao atao ny misintona ny taratasinao sy ny faktiorao amin''ny endrika PDF. Mba hahazoana kopia feno amin''ny rakitrao dia alefaso any amin''ny sekretariat ny fangatahana an-tsoratra.'),
('en', 'text:h:83bab8eb:163', 'It is generated at the end of the consultation and appears immediately in your space, “My invoices” section. You can pay it at the counter or online.'),
('mg', 'text:h:83bab8eb:163', 'Noforonina amin''ny fiafaran''ny fifampidinihana ary miseho avy hatrany eo amin''ny toerana misy anao, fizarana "Ny faktiorako". Azonao atao ny mandoa izany amin''ny kaontera na amin''ny Internet.'),
('en', 'text:h:95db831d:167', 'The PDF invoice contains all the required information. If your organization requires a specific document, contact the billing department with your membership number.'),
('mg', 'text:h:95db831d:167', 'Ny faktiora PDF dia ahitana ny fampahalalana ilaina rehetra. Raha mila antontan-taratasy manokana ny fikambananao dia mifandraisa amin''ny sampan-draharaha momba ny faktiora miaraka amin''ny laharan''ny maha-mpikambana anao.'),
('en', 'text:Signalez-la via le formulaire de contact en précisant le numéro de facture. Une régularisation est généralement traitée sous 48h ouvrées.', 'Report it via the contact form, specifying the invoice number. A regularization is generally processed within 48 working hours.'),
('mg', 'text:Signalez-la via le formulaire de contact en précisant le numéro de facture. Une régularisation est généralement traitée sous 48h ouvrées.', 'Mitatitra izany amin''ny alàlan''ny taratasy fifandraisana, manondro ny laharan''ny faktiora. Amin''ny ankapobeny dia atao ao anatin''ny 48 ora fiasana ny fanaraha-maso.'),
('en', 'text:Aide & questions fréquentes', 'Help & FAQs'),
('mg', 'text:Aide & questions fréquentes', 'Fanampiana & FAQ'),
('en', 'text:Rendez-vous, téléconsultation, dossier médical, facturation : retrouvez les réponses aux questions les plus courantes.', 'Appointments, teleconsultations, medical files, billing: find the answers to the most common questions.'),
('mg', 'text:Rendez-vous, téléconsultation, dossier médical, facturation : retrouvez les réponses aux questions les plus courantes.', 'Fanendrena, fifampidinihana an-telefaona, rakitra ara-pitsaboana, faktiora: tadiavo ny valin''ireo fanontaniana mahazatra indrindra.'),
('en', 'text:URGENCES MÉDICALES', 'MEDICAL EMERGENCIES'),
('en', 'text:MESSAGE BIEN REÇU', 'MESSAGE WELL RECEIVED'),
('mg', 'text:MESSAGE BIEN REÇU', 'RESAKA TSARA NY HAFATRA'),
('en', 'text:MÉTRO LIGNE 8 — ARRÊT « SANTÉ » · PARKING VISITEURS SUR PLACE', 'METRO LINE 8 — “HEALTH” STOP · VISITORS PARKING ON SITE'),
('mg', 'text:UNE ÉQUIPE À VOTRE ÉCOUTE,', 'Ekipa iray mihaino anao,'),
('mg', 'text:VOS DONNÉES NE SONT UTILISÉES QUE POUR TRAITER VOTRE DEMANDE.', 'NY DATA-nao dia ampiasaina hanohizana ny fangatahanao.'),
('en', 'text:TOUTES LES RÉPONSES,', 'ALL THE ANSWERS,'),
('en', 'text:AU MÊME ENDROIT', 'IN THE SAME PLACE'),
('en', 'text:h:6f87cf56:231', 'YOU CAN BOOK ONLINE FROM THE “MAKE AN APPOINTMENT” PAGE, CHOOSE YOUR PRACTITIONER AND YOUR SLOT, THEN RECEIVE IMMEDIATE CONFIRMATION. THE SECRETARIAT CAN BE CONTACTED BY TELEPHONE FOR SPECIAL REQUESTS.'),
('mg', 'text:h:6f87cf56:231', 'AFAKA MIBAKA AN-tserasera AO AVY AO AMIN''NY PEJY "MADIO FANDINIHANA", FIFIDY NY MPANAO ANAO SY NY SLOT ANAO, DIA HANAO FAHAGAGANA AVY. AZO TONGA AMIN''NY TELEFONINA NY SECRETARIAT AMIN''NY FANGATAHANA MANOKANA.'),
('en', 'text:PUIS-JE ANNULER OU DÉPLACER UN RENDEZ-VOUS ?', 'CAN I CANCEL OR MOVE AN APPOINTMENT?'),
('mg', 'text:PUIS-JE ANNULER OU DÉPLACER UN RENDEZ-VOUS ?', 'AZO ATAO MANDRAKIZAY NA MANDIKA FANENDRENANA?'),
('en', 'text:h:c0074a8f:191', 'YES. FROM YOUR PATIENT AREA, SELECT THE APPOINTMENT CONCERNED THEN CHOOSE “CANCEL”. PLEASE NOTIFY AT LEAST 24 HOURS IN ADVANCE IN ORDER TO FREE THE SLOT FOR ANOTHER PATIENT.'),
('mg', 'text:h:c0074a8f:191', 'ENY. AVY AO AMIN''NY FARITAN''NY MARARY ANAO, FIFIDY NY FANDAHARANA IZANY DIA FIFIDY "CANCEL". MBA Ampandrenesina 24 ora mialohan''ny fotoana, mba hanafaka ny slot ho an''ny marary hafa.'),
('en', 'text:h:d585b66c:191', 'YOUR VITAL CARD, AN IDENTITY PROOF, YOUR MUTUAL CARD AND, IF POSSIBLE, YOUR PRESCRIPTIONS AND RECENT ANALYSIS RESULTS. FOR A FIRST APPOINTMENT, ARRIVE TEN MINUTES EARLY.'),
('mg', 'text:h:d585b66c:191', 'NY KARARA VITAL ANAO, NY POROFO INDRINDRA, NY KARATANA IANAREO ARY, RAHA AZO AZO, NY FOTOANAO SY NY VALINY FAHAFATESANA. HO FANENDRENANA VOALOHANY DIA MITONDRA FOLO MINIT aloha.'),
('en', 'text:LA TÉLÉCONSULTATION EST-ELLE REMBOURSÉE ?', 'IS THE TELECONSULTATION REIMBURSED?'),
('mg', 'text:LA TÉLÉCONSULTATION EST-ELLE REMBOURSÉE ?', 'AVERINA VE NY TELECONSULTATION ?'),
('en', 'text:h:4dfa3349:180', 'IT IS COVERED UNDER THE SAME CONDITIONS AS AN OFFICE CONSULTATION, IF IT IS CARRIED OUT BY AN APPROVED DOCTOR. YOUR MUTUAL MUTUAL CAN COMPLETE THE REIMBURSEMENT.'),
('mg', 'text:h:4dfa3349:180', 'SARONANA MITOVY NY FEPETRA HO AN''NY FIKAMBANAN''NY BIRAO, RAHA DOKOTERA NANJAKA NO ATAONY. AFAKA MAHITA NY FIVORIANA NY FAMPIANARANA IANAREO.'),
('en', 'text:COMMENT ACCÉDER À MA VISIOCONFÉRENCE ?', 'HOW DO I ACCESS MY VIDEO CONFERENCE?'),
('mg', 'text:COMMENT ACCÉDER À MA VISIOCONFÉRENCE ?', 'AHOANA NO HIDIRANKO NY VIDEO CONFERENCE?'),
('en', 'text:h:1dff84c:157', 'ONCE YOUR REQUEST IS APPROVED, A SECURE LINK APPEARS IN “MY TELECONSULTATIONS”. THE CONNECTION BUTTON ACTIVATES TEN MINUTES BEFORE THE SCHEDULED TIME.'),
('mg', 'text:h:1dff84c:157', 'REHEFA EKENA NY FANGATAHANAO, MISEHO AO AMIN''NY "TELECONSULTATIONS" ny ROY AZY. NY BOTOANA Fifandraisana dia miasa folo minitra alohan''ny fotoana voatondro.'),
('en', 'text:QUEL MATÉRIEL EST NÉCESSAIRE ?', 'WHAT EQUIPMENT IS NEEDED?'),
('mg', 'text:QUEL MATÉRIEL EST NÉCESSAIRE ?', 'INONA NO FITAOVANA ILAINA?'),
('en', 'text:h:aa6b305d:171', 'A COMPUTER OR RECENT SMARTPHONE, A STABLE INTERNET CONNECTION, A WEBCAM AND A MICROPHONE. A QUIET AND BRIGHT PLACE CLEARLY IMPROVES THE QUALITY OF THE EXCHANGE.'),
('mg', 'text:h:aa6b305d:171', 'Solosaina na SMARTPHONE vao haingana, CONNECTION INTERNET STABLE, WEBCAM SY MICROPHONE. TOERANA MASINA SY MAZAVA MAZAVA MANAMBARA NY KAALITAN''NY FIVAROTANA.'),
('en', 'text:COMMENT CRÉER MON ESPACE PATIENT ?', 'HOW DO I CREATE MY PATIENT SPACE?'),
('mg', 'text:COMMENT CRÉER MON ESPACE PATIENT ?', 'AHOANA NO ATAO ATAO ATAO ATAO ATAO ATAO ATAO ATAO NY FAHAHARIAN''NY MARARY?'),
('en', 'text:h:8e99e312:169', 'CLICK ON “CREATE MY SPACE”, FILL IN YOUR INFORMATION AND VALIDATE YOUR EMAIL. YOU CAN THEN CONSULT YOUR APPOINTMENTS, PRESCRIPTIONS, RESULTS AND INVOICES.'),
('mg', 'text:h:8e99e312:169', 'CLICK NY "CREATE MY SPACE", FENOY NY FANAOVANAO ARY HANAFANA NY EMAIL. AFAKA AFAKA MANAITRA NY FANANDEMANAO, NY PRESCRIPTIONS, NY VALINY ARY INVOICES.'),
('en', 'text:MES DONNÉES SONT-ELLES PROTÉGÉES ?', 'IS MY DATA PROTECTED?'),
('mg', 'text:MES DONNÉES SONT-ELLES PROTÉGÉES ?', 'Arovana ve ny angonako?'),
('en', 'text:h:97bd298:167', 'YES. HEALTH DATA IS HOSTED IN FRANCE, ENCRYPTED AND ACCESSIBLE ONLY TO AUTHORIZED PROFESSIONALS. EACH ACCESS IS LOGGED IN ACCORDANCE WITH THE GDPR.'),
('mg', 'text:h:97bd298:167', 'ENY. ATAO AMIN''NY FRANTSAY NY DATA ARA-PAHASALAMANA, AZO ATAO ATAO ARY AZO AZO ATAO HO AN''NY MAFAHASALAMANA MAHAVITA IHANY. MIARAKA AMIN''NY GDPR ny fidirana tsirairay.'),
('en', 'text:PUIS-JE TÉLÉCHARGER MON DOSSIER ?', 'CAN I DOWNLOAD MY FILE?'),
('mg', 'text:PUIS-JE TÉLÉCHARGER MON DOSSIER ?', 'AFAKA HITONDRA NY FILE-KO?'),
('en', 'text:h:b2244bd9:160', 'YOU CAN DOWNLOAD YOUR PRESCRIPTIONS AND BILLS IN PDF FORMAT. TO OBTAIN A COMPLETE COPY OF YOUR FILE, SEND A WRITTEN REQUEST TO THE SECRETARIAT.'),
('mg', 'text:h:b2244bd9:160', 'AFAKA MIsintona ny PRESCRIPTIONS SY VOALOHANY AMIN''NY PDF FORMAT. MBA HAHAZO KOPIRINA FENO NY DIRA-ANAO, MANDEFA FANGATAHANA ANORATRA AMIN''NY SECRETARIAT.'),
('en', 'text:h:8180d10b:163', 'IT IS GENERATED AFTER THE CONSULTATION AND APPEARS IMMEDIATELY IN YOUR SPACE, “MY INVOICES” SECTION. YOU CAN PAY IT AT THE COUNTER OR ONLINE.'),
('mg', 'text:h:8180d10b:163', 'VOAKA AORIAN''NY FIANARANA IZANY ARY MISEHO EO AMIN''NY Espace-nao, FIZARANA "MY INVOICES". AFAKA MANDOA ENY AMIN''NY COUNTER NA ONLINE.'),
('en', 'text:h:bb23e61d:167', 'THE PDF INVOICE CONTAINS ALL THE REQUIRED NOTICES. IF YOUR ORGANIZATION REQUESTS A SPECIFIC DOCUMENT, CONTACT THE BILLING DEPARTMENT WITH YOUR MEMBER NUMBER.'),
('mg', 'text:h:bb23e61d:167', 'MISY NY FILAZANA ILAINA REHETRA IREO FOTOTRA PDF. RAHA MANGATAKA TOROHEVITRA MANKASITRAKA NY FIKAMBANANANAO, Mifandraisa amin''ny sampan-draharahan''ny faktiora miaraka amin''ny laharan''ny maha-mpikambana anao.'),
('en', 'text:SIGNALEZ-LA VIA LE FORMULAIRE DE CONTACT EN PRÉCISANT LE NUMÉRO DE FACTURE. UNE RÉGULARISATION EST GÉNÉRALEMENT TRAITÉE SOUS 48H OUVRÉES.', 'REPORT IT VIA THE CONTACT FORM, SPECIFYING THE INVOICE NUMBER. REGULARIZATION IS GENERALLY PROCESSED WITHIN 48 WORKING HOURS.'),
('mg', 'text:SIGNALEZ-LA VIA LE FORMULAIRE DE CONTACT EN PRÉCISANT LE NUMÉRO DE FACTURE. UNE RÉGULARISATION EST GÉNÉRALEMENT TRAITÉE SOUS 48H OUVRÉES.', 'TOROHEVITRA IZANY AMIN''NY LALAN''NY Fifandraisana, TORITENY NY NUMERO INVOICE. NY FANDAHARANA DIA ATAO AMIN''NY 48 ora fiasana.'),
