('mg', 'text:RENDEZ-VOUS, TÉLÉCONSULTATION, DOSSIER MÉDICAL, FACTURATION : RETROUVEZ LES RÉPONSES AUX QUESTIONS LES PLUS COURANTES.', 'FANENDRENANA, FAMPANDROSOANA, FOTOANA MEDICAMENT, FIVORIANA: ITADY NY VALINY AMIN''NY FANONTANIANA IZANY.'),
