('en', 'text:J’ai pris rendez-vous le matin pour l’après-midi, et j’ai reçu mon ordonnance directement dans mon espace patient. Un gain de temps incroyable.', 'I made an appointment in the morning for the afternoon, and I received my prescription directly in my patient area. An incredible time saver.'),
('mg', 'text:J’ai pris rendez-vous le matin pour l’après-midi, et j’ai reçu mon ordonnance directement dans mon espace patient. Un gain de temps incroyable.', 'Nanao fotoana aho ny maraina ho an''ny tolakandro, ary nahazo ny taratasiko mivantana tany amin''ny faritra misy marary aho. Mitsitsy fotoana tsy mampino.'),
('en', 'text:La téléconsultation m’a évité un déplacement pour un simple renouvellement. Le médecin avait tout mon historique sous les yeux.', 'The teleconsultation saved me from having to travel for a simple renewal. The doctor had my entire history in front of him.'),
('mg', 'text:La téléconsultation m’a évité un déplacement pour un simple renouvellement. Le médecin avait tout mon historique sous les yeux.', 'Ny fifampidinihana tamin''ny telefaonina dia nanavotra ahy tsy voatery handeha hanao fanavaozana tsotra. Nanana ny tantarako manontolo teo anoloany ilay dokotera.'),
('en', 'text:Le secrétariat est réactif et l’équipe très humaine. On se sent accompagné du début à la fin du parcours de soin.', 'The secretariat is responsive and the team is very human. You feel supported from the beginning to the end of the treatment process.'),
('mg', 'text:Le secrétariat est réactif et l’équipe très humaine. On se sent accompagné du début à la fin du parcours de soin.', 'Ny sekretariat dia mandray andraikitra ary tena olombelona ny ekipa. Mahatsapa ianao fa tohana hatrany am-piandohana ka hatramin''ny fiafaran''ny fitsaboana.'),
('en', 'text:En ligne depuis la page « Prendre rendez-vous », ou par téléphone auprès du secrétariat. La confirmation est immédiate.', 'Online from the “Make an appointment” page, or by telephone from the secretariat. Confirmation is immediate.'),
('mg', 'text:En ligne depuis la page « Prendre rendez-vous », ou par téléphone auprès du secrétariat. La confirmation est immédiate.', 'Ao amin''ny Internet avy amin''ny pejy "Make a rendez-vous", na amin''ny telefaona avy amin''ny sekretariat. Ny fanamafisana dia avy hatrany.'),
