('mg', 'text:Puis-je consulter à distance ?', 'Afaka maka hevitra lavitra ve aho?'),
('en', 'text:Oui, la téléconsultation est disponible pour de nombreux motifs : suivi, renouvellement d’ordonnance, interprétation de résultats.', 'Yes, teleconsultation is available for many reasons: monitoring, prescription renewal, interpretation of results.'),
('mg', 'text:Oui, la téléconsultation est disponible pour de nombreux motifs : suivi, renouvellement d’ordonnance, interprétation de résultats.', 'Eny, misy antony maro ny fifampidinihana an-telefaona: fanaraha-maso, fanavaozana ny prescription, fandikana ny valiny.'),
