('en', 'text:Créez votre espace patient : ordonnances, résultats et factures y sont centralisés et téléchargeables en PDF.', 'Create your patient area: prescriptions, results and invoices are centralized there and downloadable in PDF.'),
('mg', 'text:Créez votre espace patient : ordonnances, résultats et factures y sont centralisés et téléchargeables en PDF.', 'Mamorona ny faritra misy anao marary: ny prescription, ny valiny ary ny faktiora dia miorina ao ary azo alaina amin''ny PDF.'),
('en', 'text:De la prise de rendez-vous au suivi post-consultation, chaque étape est pensée pour vous faire gagner du temps.', 'From making an appointment to post-consultation follow-up, each step is designed to save you time.'),
('mg', 'text:De la prise de rendez-vous au suivi post-consultation, chaque étape est pensée pour vous faire gagner du temps.', 'Manomboka amin''ny fanaovana fotoana ka hatramin''ny fanaraha-maso aorian''ny fifampidinihana, ny dingana tsirairay dia natao hamonjena fotoana anao.'),
