('en', 'text:J’AI PRIS RENDEZ-VOUS LE MATIN POUR L’APRÈS-MIDI, ET J’AI REÇU MON ORDONNANCE DIRECTEMENT DANS MON ESPACE PATIENT. UN GAIN DE TEMPS INCROYABLE.', 'I MADE AN APPOINTMENT IN THE MORNING FOR THE AFTERNOON, AND I RECEIVED MY PRESCRIPTION DIRECTLY IN MY PATIENT AREA. AN INCREDIBLE TIME SAVING.'),
