('mg', 'text:LE SECRÉTARIAT EST RÉACTIF ET L’ÉQUIPE TRÈS HUMAINE. ON SE SENT ACCOMPAGNÉ DU DÉBUT À LA FIN DU PARCOURS DE SOIN.', 'MAMPIHAVANA NY SECRETARIAT ARY TENA OLOM-BAHOAKA NY EKIKY. Tsapanay fa Tohanana hatrany am-piandohana ka hatramin''ny faran''ny LALANA FITIAVANA.'),
('en', 'text:EN LIGNE DEPUIS LA PAGE « PRENDRE RENDEZ-VOUS », OU PAR TÉLÉPHONE AUPRÈS DU SECRÉTARIAT. LA CONFIRMATION EST IMMÉDIATE.', 'ONLINE FROM THE “MAKE AN APPOINTMENT” PAGE, OR BY TELEPHONE TO THE SECRETARIAT. CONFIRMATION IS IMMEDIATE.'),
