('en', 'news.preparer-sa-consultation.excerpt', 'An effective consultation is being prepared. List of symptoms, current treatments, questions to ask: our advice to make the most of your time with your doctor.'),
('mg', 'news.preparer-sa-consultation.excerpt', 'Misy ny fifampidinihana mahomby eo am-panomanana. Lisitr''ireo soritr''aretina, fitsaboana amin''izao fotoana izao, fanontaniana apetraka: ny torohevitr''izy ireo mba hanararaotra ny fotoananao miaraka amin''ny dokotera.'),
('en', 'news.preparer-sa-consultation.category', 'Advice'),
('mg', 'news.preparer-sa-consultation.category', 'Torohevitra'),
('en', 'news.preparer-sa-consultation.author', 'Dr Claire Martin'),
('mg', 'news.preparer-sa-consultation.author', 'Dr Claire Martin'),
('en', 'news.preparer-sa-consultation.content.0', 'The time for a consultation is limited. Note how long ago the symptoms started, how they progressed, and what aggravates or relieves them.'),
('mg', 'news.preparer-sa-consultation.content.0', 'Voafetra ny fotoana hanaovana fifampidinihana. Mariho hoe hafiriana no niantombohan’ireo soritr’aretina, ny fomba nandrosoany, ary inona no mampitombo na manamaivana azy.'),
('en', 'news.preparer-sa-consultation.content.1', 'Bring a list of your current treatments, including non-prescription medications and dietary supplements.'),
('mg', 'news.preparer-sa-consultation.content.1', 'Mitondrà lisitry ny fitsaboana anao amin''izao fotoana izao, anisan''izany ny fanafody tsy misy prescription sy ny fanampin-tsakafo.'),
('en', 'news.preparer-sa-consultation.content.2', 'Write down your questions in advance: a simple memo on your phone is enough.'),
('mg', 'news.preparer-sa-consultation.content.2', 'Soraty mialoha ny fanontanianao: memo tsotra amin''ny findainao dia ampy.'),
('en', 'news.preparer-sa-consultation.key_points.0', 'Note the timing and intensity of symptoms.'),
('mg', 'news.preparer-sa-consultation.key_points.0', 'Mariho ny fotoana sy ny hamafin''ny soritr''aretina.'),
('en', 'news.preparer-sa-consultation.key_points.1', 'List all your treatments.'),
('mg', 'news.preparer-sa-consultation.key_points.1', 'Tanisao ny fitsaboanao rehetra.'),
('en', 'news.preparer-sa-consultation.key_points.2', 'Prepare two or three priority questions.'),
('mg', 'news.preparer-sa-consultation.key_points.2', 'Manomàna fanontaniana roa na telo laharam-pahamehana.'),
('en', 'news.preparer-sa-consultation.key_points.3', 'Bring your recent exams.'),
('mg', 'news.preparer-sa-consultation.key_points.3', 'Ento ny fanadinanao vao haingana.'),
('en', 'news.teleconsultation-mode-emploi.title', 'Teleconsultation: instructions for use and good practices'),
('mg', 'news.teleconsultation-mode-emploi.title', 'Teleconsultation: torolàlana ampiasaina sy fomba fanao tsara'),
('en', 'news.teleconsultation-mode-emploi.excerpt', 'Medical videoconferencing is practical, but it requires a minimum of preparation. Here''s how to make your teleconsultation as useful as an in-person consultation.'),
('mg', 'news.teleconsultation-mode-emploi.excerpt', 'Ny fihaonambe ara-pitsaboana dia azo ampiharina, saingy mitaky fiomanana kely indrindra izany. Ity ny fomba hahatonga ny fifampidinihana amin''ny telefaonina ho mahasoa toy ny fifampidinihana manokana.'),
('en', 'news.teleconsultation-mode-emploi.category', 'Digital'),
('mg', 'news.teleconsultation-mode-emploi.category', 'Hafanàm-po'),
('en', 'news.teleconsultation-mode-emploi.author', 'MediClinic Team'),
('mg', 'news.teleconsultation-mode-emploi.author', 'Ekipa MediClinic'),
('en', 'news.teleconsultation-mode-emploi.content.0', 'Teleconsultation is suitable for monitoring chronic diseases, renewing prescriptions and interpreting results.'),
('mg', 'news.teleconsultation-mode-emploi.content.0', 'Ny teleconsultation dia mety amin''ny fanaraha-maso ny aretina mitaiza, ny fanavaozana ny prescription ary ny fandikana ny valiny.'),
('en', 'news.teleconsultation-mode-emploi.content.1', 'Sit in a quiet place and check your connection a few minutes before time.'),
('mg', 'news.teleconsultation-mode-emploi.content.1', 'Mipetraha amin''ny toerana mangina ary jereo ny fifandraisanao minitra vitsy alohan''ny fotoana.'),
('en', 'news.teleconsultation-mode-emploi.content.2', 'Describe your symptoms precisely and check the dosage at the end of the exchange.'),
('mg', 'news.teleconsultation-mode-emploi.content.2', 'Lazao tsara ny soritr''aretinao ary jereo ny dosage amin''ny faran''ny fifanakalozana.'),
('en', 'news.teleconsultation-mode-emploi.key_points.0', 'Test your equipment before the appointment.'),
('mg', 'news.teleconsultation-mode-emploi.key_points.0', 'Andramo ny fitaovanao alohan''ny fotoana.'),
('en', 'news.teleconsultation-mode-emploi.key_points.1', 'Prepare your documents and constants.'),
('mg', 'news.teleconsultation-mode-emploi.key_points.1', 'Omano ny antontan-taratasinao sy ny tsy miovaova.'),
('en', 'news.teleconsultation-mode-emploi.key_points.2', 'Choose a calm and bright place.'),
('mg', 'news.teleconsultation-mode-emploi.key_points.2', 'Mifidiana toerana tony sy mamirapiratra.'),
('en', 'news.teleconsultation-mode-emploi.key_points.3', 'Ask for a written report.'),
('mg', 'news.teleconsultation-mode-emploi.key_points.3', 'Mangataha tatitra an-tsoratra.'),
('en', 'news.prevention-cardiovasculaire.title', 'Cardiovascular prevention: actions that count'),
('mg', 'news.prevention-cardiovasculaire.title', 'Fisorohana ny aretim-po: hetsika izay isaina'),
('en', 'news.prevention-cardiovasculaire.excerpt', 'Physical activity, diet, sleep, blood pressure: concrete levers to take care of your heart on a daily basis, at any age.'),
('mg', 'news.prevention-cardiovasculaire.excerpt', 'Ny asa ara-batana, ny sakafo, ny torimaso, ny tosi-drà: fitaovana beton mba hikarakarana ny fonao isan''andro, amin''ny taona rehetra.'),
('en', 'news.prevention-cardiovasculaire.category', 'Prevention'),
('mg', 'news.prevention-cardiovasculaire.category', 'Fisorohana'),
('en', 'news.prevention-cardiovasculaire.author', 'Dr Antoine Lefèvre'),
('mg', 'news.prevention-cardiovasculaire.author', 'Dr Antoine Lefèvre'),
('en', 'news.prevention-cardiovasculaire.content.0', 'A significant proportion of cardiovascular risk factors are modifiable: tobacco, sedentary lifestyle, excess weight, hypertension, diabetes and cholesterol.'),
('mg', 'news.prevention-cardiovasculaire.content.0', 'Ny ampahany lehibe amin''ny anton-javatra mety hampidi-doza ho an''ny fo dia azo ovaina: paraky, fomba fiaina mipetrapetraka, lanjany be loatra, fiakaran''ny tosidrà, diabeta ary kolesterola.'),
('en', 'news.prevention-cardiovasculaire.content.1', 'Thirty minutes of moderate physical activity five times a week significantly reduces the risk.'),
('mg', 'news.prevention-cardiovasculaire.content.1', 'Telopolo minitra ny fanaovana fanatanjahan-tena antonony in-dimy isan-kerinandro dia mampihena be ny risika.'),
('en', 'news.prevention-cardiovasculaire.content.2', 'Favor vegetables, fruits and whole grains while limiting ultra-processed products, salt and alcohol.'),
('mg', 'news.prevention-cardiovasculaire.content.2', 'Ankafizo ny legioma, voankazo ary voamaina manontolo raha mametra ny vokatra voahodina, sira ary alikaola.'),
('en', 'news.prevention-cardiovasculaire.key_points.0', 'Move at least 30 minutes a day.'),
('mg', 'news.prevention-cardiovasculaire.key_points.0', 'Mandrosoa farafahakeliny 30 minitra isan''andro.'),
('en', 'news.prevention-cardiovasculaire.key_points.1', 'Have your blood pressure checked once a year.'),
('mg', 'news.prevention-cardiovasculaire.key_points.1', 'Asaivo jerena indray mandeha isan-taona ny tosidra.'),
('en', 'news.prevention-cardiovasculaire.key_points.2', 'Reduce salt, alcohol and tobacco.'),
('mg', 'news.prevention-cardiovasculaire.key_points.2', 'Ahena ny sira, ny alikaola ary ny paraky.'),
('en', 'news.prevention-cardiovasculaire.key_points.3', 'Consult in case of chest pain.'),
('mg', 'news.prevention-cardiovasculaire.key_points.3', 'Manoro hevitra raha marary tratra.'),
('en', 'news.sommeil-et-sante.title', 'Sleep and health: rebuilding restful nights'),
('mg', 'news.sommeil-et-sante.title', 'Matory sy fahasalamana: manangana indray alina milamina'),
('en', 'news.sommeil-et-sante.excerpt', 'Lack of sleep affects mood, immunity and cardiometabolic risk. A few simple routines can often improve the quality of the night.'),
('mg', 'news.sommeil-et-sante.excerpt', 'Ny tsy fahampian''ny torimaso dia misy fiantraikany amin''ny toe-po, ny tsy fahampiana ary ny risika cardiometabolic. Ny fanao tsotra vitsivitsy dia matetika afaka manatsara ny kalitaon''ny alina.'),
('en', 'news.sommeil-et-sante.category', 'Well-being'),
('mg', 'news.sommeil-et-sante.category', '-Panahy'),
('en', 'news.sommeil-et-sante.author', 'Dr Sophie Bernard'),
('mg', 'news.sommeil-et-sante.author', 'Dr Sophie Bernard'),
('en', 'news.sommeil-et-sante.content.0', 'An adult needs seven to nine hours of sleep; the regularity of schedules is often more important than the duration.'),
('mg', 'news.sommeil-et-sante.content.0', 'Ny olon-dehibe iray dia mila adiny fito ka hatramin''ny sivy; ny fizotry ny fandaharam-potoana matetika dia manan-danja kokoa noho ny faharetany.'),
('en', 'news.sommeil-et-sante.content.1', 'Avoid bright screens in the hour before bed and caffeine after 2 p.m.'),
('mg', 'news.sommeil-et-sante.content.1', 'Fadio ny efijery mamirapiratra amin''ny ora alohan''ny hatoriana sy ny kafeinina aorian''ny 2 ora.'),
('en', 'news.sommeil-et-sante.content.2', 'If difficulties last more than three weeks, talk to your doctor.'),
('mg', 'news.sommeil-et-sante.content.2', 'Raha maharitra mihoatra ny telo herinandro ny fahasarotana, miresaha amin''ny dokoteranao.'),
('en', 'news.sommeil-et-sante.key_points.0', 'Go to bed and get up at regular times.'),
('mg', 'news.sommeil-et-sante.key_points.0', 'Mandehana matory ary mifohaza amin''ny fotoana tsy tapaka.'),
('en', 'news.sommeil-et-sante.key_points.1', 'Limit screens in the evening.'),
('mg', 'news.sommeil-et-sante.key_points.1', 'Fepetra ny efijery amin''ny hariva.'),
('en', 'news.sommeil-et-sante.key_points.2', 'Avoid caffeine at the end of the day.'),
('mg', 'news.sommeil-et-sante.key_points.2', 'Fadio ny kafeinina amin''ny faran''ny andro.'),
('en', 'news.sommeil-et-sante.key_points.3', 'Consult if problems persist.'),
('mg', 'news.sommeil-et-sante.key_points.3', 'Miresaha raha mbola mitohy ny olana.'),
('en', 'news.vaccination-adulte.title', 'Adult vaccination: are you up to date?'),
('mg', 'news.vaccination-adulte.title', 'Vaksina ho an''ny olon-dehibe: manara-maso ve ianao?'),
('en', 'news.vaccination-adulte.excerpt', 'Diphtheria, tetanus, whooping cough, flu, shingles… Vaccination boosters also concern adults. Check with your doctor.'),
('mg', 'news.vaccination-adulte.excerpt', 'Ny difteria, ny tetanosy, ny kohaka, ny gripa, ny shingles… Ny fampiroboroboana ny vaksiny dia mahakasika ny olon-dehibe ihany koa. Jereo amin''ny dokoteranao.'),
('en', 'news.vaccination-adulte.category', 'Prevention'),
('mg', 'news.vaccination-adulte.category', 'Fisorohana'),
('en', 'news.vaccination-adulte.author', 'Dr Claire Martin'),
('mg', 'news.vaccination-adulte.author', 'Dr Claire Martin'),
('en', 'news.vaccination-adulte.content.0', 'Vaccination recommendations change with age, pregnancy, chronic illnesses or travel.'),
('mg', 'news.vaccination-adulte.content.0', 'Miova arakaraka ny taonany, ny fitondrana vohoka, ny aretina mitaiza na ny dia ny tolo-kevitry ny fanaovana vaksiny.'),
('en', 'news.vaccination-adulte.content.1', 'The diphtheria-tetanus-pertussis booster is recommended every twenty years in adulthood.'),
('mg', 'news.vaccination-adulte.content.1', 'Ny diphtheria-tetanus-pertussis booster dia atolotra isaky ny roapolo taona amin''ny olon-dehibe.'),
('en', 'news.vaccination-adulte.content.2', 'The clinic offers walk-in vaccination sessions on certain afternoons.'),
('mg', 'news.vaccination-adulte.content.2', 'Ny tobim-pitsaboana dia manolotra fivoriana fanaovana vaksiny mandeha an-tongotra amin''ny tolakandro sasany.'),
('en', 'news.vaccination-adulte.key_points.0', 'Check your vaccination record.'),
('mg', 'news.vaccination-adulte.key_points.0', 'Jereo ny firaketanao momba ny vaksiny.'),
('en', 'news.vaccination-adulte.key_points.1', 'DTP reminder every 20 years.'),
('mg', 'news.vaccination-adulte.key_points.1', 'Fampahatsiahivana DTP isaky ny 20 taona.'),
('en', 'news.vaccination-adulte.key_points.2', 'Flu vaccination every fall.'),
('mg', 'news.vaccination-adulte.key_points.2', 'Vaksina gripa isaky ny fararano.'),
('en', 'news.vaccination-adulte.key_points.3', 'Report pregnancy and chronic illnesses.'),
('mg', 'news.vaccination-adulte.key_points.3', 'Tatitra momba ny fitondrana vohoka sy ny aretina mitaiza.'),
('en', 'news.dossier-medical-numerique.title', 'Your digital medical record, instructions for use'),
('mg', 'news.dossier-medical-numerique.title', 'Ny firaketana ara-pitsaboana nomerika anao, torolàlana ampiasaina'),
('en', 'news.dossier-medical-numerique.excerpt', 'Prescriptions, analysis results and centralized reports: find out how to use your patient area and protect your identifiers.'),
('mg', 'news.dossier-medical-numerique.excerpt', 'Prescription, valim-panadihadiana ary tatitra afovoany: fantaro ny fomba fampiasana ny faritra misy anao ary arovy ny famantarana anao.'),
('en', 'news.dossier-medical-numerique.category', 'Digital'),
('mg', 'news.dossier-medical-numerique.category', 'Hafanàm-po'),
('en', 'news.dossier-medical-numerique.author', 'MediClinic Team'),
('mg', 'news.dossier-medical-numerique.author', 'Ekipa MediClinic'),
('en', 'news.dossier-medical-numerique.content.0', 'Your patient area includes prescriptions, laboratory results, reports and invoices.'),
('en', 'news.dossier-medical-numerique.content.1', 'Access is protected by authentication: never share your password.'),
('en', 'news.dossier-medical-numerique.content.2', 'You can download your documents in PDF format to send them to another professional.'),
('en', 'news.dossier-medical-numerique.key_points.0', 'A single space for all your documents.'),
('en', 'news.dossier-medical-numerique.key_points.1', 'Secure, logged connection.'),
('mg', 'news.dossier-medical-numerique.key_points.1', 'Fifandraisana azo antoka, voarakitra.'),
('en', 'news.dossier-medical-numerique.key_points.2', 'PDF download available.'),
('mg', 'news.dossier-medical-numerique.key_points.2', 'PDF azo alaina.'),
('en', 'news.dossier-medical-numerique.key_points.3', 'Never share your identifiers.'),
('en', 'clinic.address', '12 avenue de la Santé, 75015 Paris, France'),
('mg', 'clinic.address', '12 avenue de la Santé, 75015 Paris, France'),
